// Split the stdout into individual folder paths
const stdout = $input.first().json.stdout;
const folders = stdout.trim().split('\n').filter(folder => folder.length > 0);

const items = folders.map(folder => ({
  json: {
    folder_path: folder,
    folder_name: folder.split('/').pop()
  }
}));

return items;

// Get all items from the input
const items = $input.all();

// Track occurrences of each sample ID
const sampleIdCounts = {};

// First pass: count occurrences (trimming whitespace)
items.forEach(item => {
  const sampleId = String(item.json.Sample_ID || '').trim();
  if (sampleId) {  // Only count if not empty
    sampleIdCounts[sampleId] = (sampleIdCounts[sampleId] || 0) + 1;
  }
});

// Track which occurrence we're on for each ID
const currentOccurrence = {};

// Second pass: rename duplicates
const processedItems = items.map(item => {
  const rawSampleId = item.json.Sample_ID;

  // Handle null, undefined, or non-string values
  if (rawSampleId == null) {
    return item;  // Skip items without Sample_ID
  }

  const sampleId = String(rawSampleId).trim();

  if (!sampleId) {
    return item;  // Skip empty Sample_IDs
  }

  // Initialize counter if first time seeing this ID
  if (!currentOccurrence[sampleId]) {
    currentOccurrence[sampleId] = 1;
  }

  // If this ID appears more than once
  if (sampleIdCounts[sampleId] > 1) {
    // First occurrence: no suffix
    if (currentOccurrence[sampleId] === 1) {
      item.json.Sample_ID = sampleId;
    } else {
      // Second and beyond: add suffix
      item.json.Sample_ID = `${sampleId}-${currentOccurrence[sampleId]}`;
    }
    currentOccurrence[sampleId] += 1;
  } else {
    // Only one occurrence, clean up whitespace
    item.json.Sample_ID = sampleId;
  }

  return item;
});

return processedItems;

// Function to normalize text to ASCII
function normalizeToAscii(text) {
  if (typeof text !== 'string') {
    return text;
  }

  // Normalize Unicode characters (NFKD decomposition)
  let normalized = text.normalize('NFKD');

  // Remove diacritical marks and non-ASCII characters
  normalized = normalized.replace(/[\u0300-\u036f]/g, '');

  // Convert Turkish-specific characters manually
  const turkishMap = {
    'ı': 'i', 'İ': 'I',
    'ğ': 'g', 'Ğ': 'G',
    'ü': 'u', 'Ü': 'U',
    'ş': 's', 'Ş': 'S',
    'ö': 'o', 'Ö': 'O',
    'ç': 'c', 'Ç': 'C'
  };

  // Replace Turkish characters
  Object.keys(turkishMap).forEach(char => {
    normalized = normalized.replace(new RegExp(char, 'g'), turkishMap[char]);
  });

  // Keep only ASCII characters
  normalized = normalized.replace(/[^\x00-\x7F]/g, '');

  // Replace non-alphanumeric characters with dashes
  normalized = normalized.replace(/[^a-zA-Z0-9]+/g, '-');

  // Remove leading/trailing dashes
  normalized = normalized.replace(/^-+|-+$/g, '');

  return normalized;
}

// Process all items
const items = $input.all();

const processedItems = items.map(item => {
  const processedJson = {};

  // Normalize all string fields
  Object.keys(item.json).forEach(key => {
    processedJson[key] = normalizeToAscii(item.json[key]);
  });

  return { json: processedJson };
});

return processedItems;

