// Function to get reverse complement of a DNA sequence
function reverseComplement(seq) {
  const complement = {
    'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G',
    'a': 't', 't': 'a', 'g': 'c', 'c': 'g',
    'N': 'N', 'n': 'n'
  };
  return seq.split('').reverse().map(base => complement[base] || base).join('');
}

